$string['configsitemaxcategorydepthhelp'] = 'Tùy chọn này chỉ định độ sâu tối đa của các danh mục con được mở rộng khi hiển thị danh mục hoặc danh sách kết hợp. Các danh mục ở cấp sâu hơn sẽ xuất hiện dưới dạng liên kết và người dùng có thể mở rộng chúng bằng yêu cầu AJAX.';
$string['configslasharguments'] = '\'Tham số dấu gạch chéo\' (sử dụng <em>PATH_INFO</em>) là cần thiết để các gói SCORM và tài nguyên nhiều tệp hiển thị chính xác. Nếu máy chủ web không hỗ trợ \'tham số dấu gạch chéo\' và bạn không thể cấu hình, có thể tắt tùy chọn này, nhưng điều đó sẽ khiến một số chức năng không hoạt động.<br />Lưu ý: Các phiên bản Moodle trong tương lai sẽ yêu cầu sử dụng \'tham số dấu gạch chéo\'.';
$string['configsmtpauthtype'] = 'Tùy chọn này đặt loại xác thực sẽ sử dụng trên máy chủ SMTP.';
$string['configsmtphosts'] = 'Nhập tên đầy đủ của một hoặc nhiều máy chủ SMTP cục bộ mà Moodle sẽ sử dụng để gửi thư (ví dụ: \'mail.a.com\' hoặc \'mail.a.com;mail.b.com\'). Để chỉ định cổng không mặc định (tức là cổng khác 25), hãy dùng cú pháp [server]:[port] (ví dụ: \'mail.a.com:587\'). Để kết nối an toàn, thường dùng cổng 465 với SSL và cổng 587 với Transport Layer Security (TLS). Nếu cần, hãy chỉ định giao thức bảo mật bên dưới. Nếu để trống trường này, Moodle sẽ dùng phương thức gửi thư mặc định của PHP.';
$string['configsmtpmaxbulk'] = 'Số lượng thư tối đa được gửi trong mỗi phiên SMTP. Gom nhóm thư có thể tăng tốc độ gửi email. Giá trị nhỏ hơn 2 sẽ buộc tạo phiên SMTP mới cho mỗi email.';
$string['configsmtpoauthservice'] = 'Chọn dịch vụ OAuth 2 đã được cấu hình để giao tiếp với máy chủ SMTP. Nếu dịch vụ chưa tồn tại, bạn cần tạo dịch vụ đó. Lưu ý rằng bạn cần đặt loại xác thực SMTP thành XOAUTH2.';
$string['configsmtpsecure'] = 'Nếu máy chủ SMTP yêu cầu kết nối an toàn, hãy chỉ định đúng loại giao thức.';
