$string['configstartwday'] = 'Ngày bắt đầu tuần';
$string['configstatsfirstrun'] = 'Tùy chọn này chỉ định khoảng thời gian nhật ký cần xử lý <b>trong lần đầu tiên</b> cronjob xử lý thống kê. Nếu trang web có nhiều lưu lượng truy cập và dùng dịch vụ lưu trữ dùng chung, có lẽ không nên chọn khoảng thời gian quá dài vì quá trình chạy có thể mất nhiều thời gian và tiêu tốn nhiều tài nguyên. (Lưu ý: với tùy chọn này, 1 tháng = 28 ngày. Trong biểu đồ và báo cáo được tạo, 1 tháng = 1 tháng dương lịch.)';
$string['configstatsmaxruntime'] = 'Quá trình xử lý thống kê có thể tiêu tốn nhiều tài nguyên; hãy kết hợp trường này với trường tiếp theo để chỉ định thời điểm chạy và thời lượng chạy.';
$string['configstatsmaxruntime2'] = 'Quá trình xử lý thống kê có thể tiêu tốn nhiều tài nguyên. Hãy chỉ định thời gian tối đa được phép để thu thập thống kê trong một ngày. Số ngày tối đa được xử lý trong mỗi lần chạy cron là 31.';
$string['configstatsmaxruntime3'] = 'Tùy chọn này chỉ định thời gian tối đa được phép để tính toán thống kê cho một ngày, lưu ý rằng quá trình xử lý thống kê có thể gây tải lớn cho máy chủ. Có thể chỉ định bên dưới số ngày tối đa được xử lý trong mỗi lần chạy cron.';
$string['configstatsruntimedays'] = 'Tùy chọn này chỉ định số ngày tối đa được xử lý trong mỗi lần chạy thống kê. Khi thống kê đã được cập nhật đầy đủ, chỉ một ngày được xử lý; vì vậy, hãy điều chỉnh giá trị này tùy theo tải máy chủ và giảm xuống nếu cần thời gian chạy cron ngắn hơn.';
